function itemLong(id){const it=IT[id];if(!it)return'';
  if(WT[id]){const r=it.slot==='ranged';const dm=r?it.dmg+2*wF(id):it.dmg+2*wF(id);
    return U(`${r?'Дальня':'Ближня'} зброя. Урон ${dm}${r?`, дальність ${it.rng}, постріл ${id==='pistol'?4:3} ОД`:`, удар ${it.wap||2} ОД${it.reach?`, дістає на ${it.reach} клітинки`:''}`}${it.pierce?`, пробиває ${it.pierce} броні`:''}, вага ${it.wt||0}. ${WT[id].tr}${wF(id)?' '+WF[id].slice(0,wF(id)).map(f=>f.tr).join(' '):''} Б’ючи нею, ти ростиш майстерність і відкриваєш прийоми.`)}
  return U(ILD[id]||it.d)}
function itemShort(id){const it=IT[id];if(!it)return'';
  if(WT[id]){const r=it.slot==='ranged';return`${r?'Дальня':'Ближня'}: урон ${it.dmg+2*wF(id)+((s.wfb||{})[id]||0)}${r?`, дальність ${it.rng}`:`, ${it.wap||2} ОД`}, вага ${it.wt||0}`}
  if(it.slot==='armor')return`Броня ${it.arm}${it.hp?`, +${it.hp} здоров’я`:''}${it.ap?`, ${it.ap} ОД`:''}, вага ${it.wt||0}`;
  if(it.slot==='light')return`Світло в руці${it.per?`, +${it.per} Пильність`:''}`;
  if(it.slot==='charm')return[it.per?`+${it.per} Пильність`:'',it.hp?`+${it.hp} здоров’я`:'',it.ap?`+${it.ap} ОД`:''].filter(Boolean).join(', ');
  if(it.use==='heal')return`Лікує ${it.v} здоров’я`;if(it.use==='net')return'Знерухомлює ворога';if(it.use==='smoke')return'Ховає від пострілів';if(it.use==='bomb')return`${it.v} урону по площі`;
  return U(it.d).split('. ')[0].replace(/\.$/,'')}
