const GLR=GLOS.map(g=>[new RegExp('(^|[^А-Яа-яІіЇїЄєҐґ’\'])('+g[0]+'[А-Яа-яІіЇїЄєҐґ’\']*)','i'),g]);
function glossify(root){if(!root||!document.createTreeWalker)return;const used={};const tw=document.createTreeWalker(root,4);const nodes=[];let n;while(n=tw.nextNode())nodes.push(n);
  for(const node of nodes){const pe=node.parentElement;if(!pe||pe.closest('button,input,.gl,#tabs,#top,pre,h2,h3'))continue;
    for(const[re,g]of GLR){if(used[g[0]])continue;const m=re.exec(node.nodeValue);if(!m)continue;used[g[0]]=1;s.glSeen=s.glSeen||{};s.glSeen[g[0]]=1;
      const at=m.index+m[1].length,w=m[2];const after=node.splitText(at);after.nodeValue=after.nodeValue.slice(w.length);
      const sp=document.createElement('span');sp.className='gl';sp.textContent=w;sp.setAttribute('data-tip',`<b>${g[1]}</b> — ${g[2]}`);node.parentNode.insertBefore(sp,after);break}}}
