const RS=[
  {id:'currents',t:1,n:'Морські течії',c:10,d:'Загорожа для плавника приносить удвічі більше.',rep:'Течії біля маяка ходять колом і щоранку несуть плавник до південного берега. Якщо поставити загорожу трохи далі від скель, вона ловитиме вдвічі більше.'},
  {id:'herbal',t:1,n:'Травництво',c:14,d:'Рецепт вересового зілля. Трав збирається вдвічі більше.',rep:'Верес, чебрець і полин, зварені разом, гоять рани швидше за будь-який бинт. Важливо зрізати лише верхівки: тоді трава відростає вдвічі густіша.'},
  {id:'render',t:1,n:'Топлення жиру',c:18,d:'Відкриває жиротопню (риба → олія) і масляні бомби.',rep:'З риб’ячого жиру виходить густа олія, яка горить довго й рівно. Її ж можна залити в глиняний горщик із ґнотом, і тоді вона горить зовсім не так мирно.'},
  {id:'metal',t:1,n:'Металургія',c:21,d:'Рецепти важчої зброї й міцнішої броні. Більше брухту з уламків.',rep:'Корабельне залізо м’яке, але чисте. Якщо проковувати його при правильному жарі, вийде добрий клинок і кільця для кольчуги.'},
  {id:'a_crab',t:1,kill:'crab',n:'Розтин краба',c:8,d:'+10% влучності й +1 урону проти крабів. Відкриває рецепт із крабового панцира.',rep:'Панцир краба найтонший під клешнями, туди й треба бити. А зі спинних пластин виходять легкі й міцні наручі.'},
  {id:'order',t:2,r:['currents'],n:'Систематизація записів',c:25,d:'Відкриває книжкові полиці.',rep:'Записи Остапа розкладені по роках, по припливах і по кораблях. Якщо поставити полиці, знання знаходитимуться швидше.'},
  {id:'signals',t:2,r:['currents'],n:'Морські сигнали',c:20,d:'Сигнальне вогнище дешевше на 30%, а кораблі лишають більше вантажу.',rep:'Капітани впізнають сигнал за ритмом вогню. Хто знає старий код хранителів, тому й вантаж скидають щедріше.'},
  {id:'tactics',t:2,r:['metal'],n:'Тактика',c:28,d:'+1 очко дії в бою. Відкриває тренувальний манекен.',rep:'Остап колись навчав береговиків: не стій на місці, бий і відходь. Опудало на подвір’ї допоможе відточити рухи.'},
  {id:'mech',t:2,r:['metal'],n:'Механізми',c:35,d:'+1 до Механіки. Відкриває лебідку на уламках.',rep:'Шестерні маяка, замки й лебідки працюють за одними правилами. Зрозумієш одне — відімкнеш інше.'},
  {id:'a_gull',t:2,kill:'gull',n:'Звички чайок',c:12,d:'+10% влучності й +1 урону проти чайок. Твої постріли завдають +1 урону.',rep:'Чайки завжди пікірують проти вітру, тож їх легко передбачити. Пір’я з крил добре стабілізує снаряд у польоті.'},
  {id:'a_eel',t:2,kill:'eel',n:'Розтин вугра',c:20,d:'+10% влучності й +1 урону проти вугрів. Коптильня й жиротопня працюють на 50% швидше.',rep:'Вугор не має луски, а його жир топиться навіть від слабкого вогню. Знаючи це, коптильня й жиротопня працюватимуть удвічі швидше.'},
  {id:'a_silent',t:2,kill:'scout',n:'Анатомія Мовчунів',c:25,d:'+10% влучності й +1 урону проти Мовчунів{gnat: і Гната|}.',rep:'Мовчуни носять шкіряні нагрудники, але бока в них відкриті. І всі вони ступають з лівої ноги, {gnat:як учив їх Гнат|так їх навчили}.'},
  {id:'a_fog',t:3,kill:'wraith',n:'Природа Мли',c:40,d:'Туманні примари більше не розчиняються, а їхній холод слабшає вдвічі.',rep:'Мла боїться рівного світла. Примари з неї — лише тіні, і в світлі ліхтаря вони не можуть сховатися.'},
  {id:'weak',t:3,r:['a_silent'],n:'Слабкі місця',c:35,d:'Усі твої атаки пробивають ще 1 броні.',rep:'Будь-яку броню тримають ремені й заклепки. Бий у них, а не в пластини.'},
  {id:'optics',t:3,r:['mech'],n:'Оптика',c:56,d:'Як склеїти велику лінзу з уламків.',rep:'Лінзу склеюють живицею й гріють, поки вона не стане прозорою. Рама має бути із заліза, інакше скло трісне від жару.'},
  {id:'a_shark',t:3,kill:'shark',n:'Морські хижаки',c:30,d:'+10% влучності й +1 урону проти акул. Пісок і скло добуваються на 25% швидше.',rep:'Акула ніколи не нападає прямо: спершу описує коло. Хто знає це коло, той знає, куди бити. А на косі, де вони полюють, пісок найчистіший.'},
  {id:'a_stone',t:3,kill:'sentinel',n:'Кам’яні вартові',c:45,d:'+10% влучності й +1 урону проти вартових. Твої атаки пробивають ще 1 броні.',rep:'Вартових вирізьбили ченці, щоб стерегти Серце. Камінь тримається на рунах, а руни — на швах. Бий у шви.'},
  {id:'beacon',t:4,r:['optics','render'],n:'Маякова справа',c:84,d:'Як запалити великий вогонь і не дати йому згаснути.',rep:'Вічний гніт, олія, лінза й чиста ліхтарня. А ще — хранитель, який не спить, поки на морі є хоч один корабель.'},
];

